// @FIGURE_CODE_BEGIN
var hDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var hFrame = setPlotFrame({ xDomain: [-6.8, 6.8], yDomain: [-5.6, 5.6], margin: 10, draw: hDraw });

var COL = {
  axis: '#000000',
  navy: '#17548c',
  orange: '#ef7043',
  teal: '#189085',
  red: '#e8473a',
  blue: '#3fa9e0',
  center: '#f07a3c',
  text: '#111111'
};

var S = 48, k = 1, FS = 14.5;
var aVal = 2.5, bVal = 2.5, viewMode = 'Guides + curve';

var gAxes = hDraw.group();
var gGuides = hDraw.group();
var gCurve = hDraw.group();
var gCo = hDraw.group();
var gTrans = hDraw.group();
var gFoci = hDraw.group();
var gLabA = hDraw.group();   // construction labels
var gLabB = hDraw.group();   // always-on labels

/* ── geometry / scale ─────────────────────────────────────────────── */
function fitAspect() {
  var m = hFrame.margin;
  var pw = Math.max(60, hFrame.width - 2 * m);
  var ph = Math.max(60, hFrame.height - 2 * m);
  S = Math.min(pw / 13.6, ph / 11.2);
  hFrame.xDomain = [-(pw / S) / 2, (pw / S) / 2];
  hFrame.yDomain = [-(ph / S) / 2, (ph / S) / 2];
  hFrame.sx = S; hFrame.sy = S;
  k = Math.max(0.45, Math.min(1.45, S / 48));
  FS = Math.max(8.5, 14.5 * k);
}

/* ── small helpers ────────────────────────────────────────────────── */
function mkText(g, str, px, py, opts) {
  opts = opts || {};
  var t = g.plain(str);
  t.font({
    family: 'Georgia, "Times New Roman", serif',
    size: opts.size || FS,
    style: opts.italic ? 'italic' : 'normal',
    anchor: 'middle'
  });
  t.attr({ x: px, y: py, 'dominant-baseline': 'central' });
  t.fill(opts.color || COL.text);
  t.attr({
    'paint-order': 'stroke', stroke: '#ffffff',
    'stroke-width': Math.max(1.6, 3.2 * k), 'stroke-linejoin': 'round'
  });
  return t;
}

function arrowHead(g, x1, y1, x2, y2, color, size) {
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var w = size * 0.42;
  var bx = x2 - size * Math.cos(ang), by = y2 - size * Math.sin(ang);
  var pts = [
    [x2, y2],
    [bx + w * Math.sin(ang), by - w * Math.cos(ang)],
    [bx - w * Math.sin(ang), by + w * Math.cos(ang)]
  ];
  g.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color).stroke('none');
}

function edgePoint(box, tx, ty, pad) {
  var cx = box.cx, cy = box.cy;
  var dx = tx - cx, dy = ty - cy;
  var hw = box.width / 2 + pad, hh = box.height / 2 + pad;
  var sx = dx !== 0 ? hw / Math.abs(dx) : Infinity;
  var sy = dy !== 0 ? hh / Math.abs(dy) : Infinity;
  var s = Math.min(sx, sy);
  if (!isFinite(s)) s = 0;
  return [cx + dx * s, cy + dy * s];
}

function inter(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(typeof tip === 'function' ? tip() : tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
}

function annot(g, str, wx, wy, twx, twy, title, body) {
  var t = mkText(g, str, plotX(wx), plotY(wy));
  var box = t.bbox();
  var tx = plotX(twx), ty = plotY(twy);
  var sp = edgePoint(box, tx, ty, 3.5 * k);
  var dx = tx - sp[0], dy = ty - sp[1], L = Math.sqrt(dx * dx + dy * dy);
  if (L > 12 * k) {
    var gap = Math.min(L * 0.3, 5.5 * k);
    var ex = tx - dx / L * gap, ey = ty - dy / L * gap;
    g.line(sp[0], sp[1], ex, ey).stroke({ color: '#111', width: Math.max(0.7, 1.05 * k), linecap: 'round' });
    arrowHead(g, sp[0], sp[1], ex, ey, '#111', 8.5 * k);
  }
  t.front();
  if (title) inter(t, str + ' — click for detail', title, body);
  return t;
}

/* ── main drawing ─────────────────────────────────────────────────── */
function drawAll() {
  var a = aVal, b = bVal, c = Math.sqrt(a * a + b * b), m = b / a;
  var xm = hFrame.xDomain[1], ym = hFrame.yDomain[1];
  var RX = Math.min(xm, 7.2), RY = Math.min(ym, 5.9);

  [gAxes, gGuides, gCurve, gCo, gTrans, gFoci, gLabA, gLabB].forEach(function (g) { g.clear(); });

  /* axes */
  var axw = Math.max(0.9, 1.7 * k), ah = 13 * k;
  var xe = xm * 0.945, ye = ym * 0.945;
  gAxes.line(plotX(-xe), plotY(0), plotX(xe), plotY(0)).stroke({ color: COL.axis, width: axw });
  arrowHead(gAxes, plotX(0), plotY(0), plotX(xe), plotY(0), COL.axis, ah);
  arrowHead(gAxes, plotX(0), plotY(0), plotX(-xe), plotY(0), COL.axis, ah);
  gAxes.line(plotX(0), plotY(-ye), plotX(0), plotY(ye)).stroke({ color: COL.axis, width: axw });
  arrowHead(gAxes, plotX(0), plotY(0), plotX(0), plotY(ye), COL.axis, ah);
  arrowHead(gAxes, plotX(0), plotY(0), plotX(0), plotY(-ye), COL.axis, ah);
  mkText(gAxes, 'x', plotX(xm * 0.985), plotY(0.42), { italic: true });
  mkText(gAxes, 'y', plotX(-0.34), plotY(ym * 0.975), { italic: true });

  /* asymptotes (orange dashed diagonals) */
  var smax = Math.min(xm * 0.99, (ym * 0.99) / m);
  var asyDash = Math.max(3, 9 * k) + ',' + Math.max(2.5, 6.5 * k);
  [1, -1].forEach(function (sg) {
    var x1 = -smax, y1 = sg * m * -smax, x2 = smax, y2 = sg * m * smax;
    gGuides.line(plotX(x1), plotY(y1), plotX(x2), plotY(y2))
      .stroke({ color: COL.orange, width: Math.max(1.1, 2.3 * k), dasharray: asyDash, linecap: 'butt' });
    var hit = gGuides.line(plotX(x1), plotY(y1), plotX(x2), plotY(y2))
      .stroke({ color: '#000', width: 12 * k, opacity: 0 });
    inter(hit, function () {
      return 'Asymptote  y = ' + (sg > 0 ? '' : '−') + (m).toFixed(2) + ' x   (slope ±b/a)';
    }, 'Asymptote', 'The extended diagonals of the guide rectangle are the lines y = ±(b/a)x. ' +
    'The branches approach them without ever touching: b/a is currently ' + (b / a).toFixed(2) + '.');
  });

  /* guide rectangle */
  var rx = plotX(-a), ryTop = plotY(b);
  var rw = plotX(a) - plotX(-a), rh = plotY(-b) - plotY(b);
  var rect = gGuides.rect(rw, rh).move(rx, ryTop).fill('none')
    .stroke({ color: COL.teal, width: Math.max(1.1, 2.1 * k), dasharray: asyDash });
  inter(rect, function () { return 'Guide rectangle: width 2a = ' + (2 * a).toFixed(1) + ', height 2b = ' + (2 * b).toFixed(1); },
    'Guide (central) rectangle',
    'Corners at (±a, ±b). Its vertical sides touch the vertices and its corners lie exactly on the asymptotes, ' +
    'so the rectangle alone determines the whole hyperbola.');

  /* branches */
  function branch(sign) {
    var T = Math.asinh((ym * 0.99) / b);
    var xlim = xm * 0.99;
    if (xlim / a > 1) T = Math.min(T, Math.acosh(xlim / a));
    var pts = [];
    for (var i = 0; i <= 160; i++) {
      var t = -T + 2 * T * i / 160;
      pts.push([plotX(sign * a * Math.cosh(t)), plotY(b * Math.sinh(t))]);
    }
    var str = pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
    gCurve.polyline(str).fill('none')
      .stroke({ color: COL.navy, width: Math.max(1.4, 3 * k), linecap: 'round', linejoin: 'round' });
    var hit = gCurve.polyline(str).fill('none').stroke({ color: '#000', width: 13 * k, opacity: 0 });
    inter(hit, function () {
      return 'x²/' + (a * a).toFixed(2) + ' − y²/' + (b * b).toFixed(2) + ' = 1';
    }, 'The hyperbola', 'Each branch satisfies x²/a² − y²/b² = 1. It turns at the vertex (±a, 0) and then ' +
    'flattens toward the asymptotes of slope ±b/a.');
  }
  branch(1); branch(-1);

  /* conjugate axis + co-vertices */
  gCo.line(plotX(0), plotY(-b), plotX(0), plotY(b))
    .stroke({ color: COL.blue, width: Math.max(1, 2 * k) });
  [b, -b].forEach(function (yv) {
    var d = gCo.circle(Math.max(3.4, 9 * k)).center(plotX(0), plotY(yv)).fill(COL.blue).stroke('none');
    inter(d, function () { return 'Co-vertex (0, ' + yv.toFixed(1) + ')'; }, 'Co-vertex',
      'The endpoints (0, ±b) of the conjugate axis. The curve never passes through them — yet b sets the ' +
      'rectangle height and therefore the asymptote slope b/a.');
  });

  /* transverse axis, vertices, center */
  gTrans.line(plotX(-a), plotY(0), plotX(a), plotY(0))
    .stroke({ color: COL.red, width: Math.max(1.6, 3.4 * k), linecap: 'butt' });
  [a, -a].forEach(function (xv) {
    var d = gTrans.circle(Math.max(3.6, 9.4 * k)).center(plotX(xv), plotY(0)).fill(COL.navy).stroke('none');
    inter(d, function () { return 'Vertex (' + xv.toFixed(1) + ', 0)'; }, 'Vertex',
      'The turning point of a branch, at (±a, 0). a is the distance from the center to a vertex, ' +
      'so it alone says where the hyperbola starts.');
  });
  var ast = gTrans.group();
  for (var i2 = 0; i2 < 3; i2++) {
    var th = i2 * Math.PI / 3, r = 0.15;
    ast.line(plotX(-r * Math.cos(th)), plotY(-r * Math.sin(th)), plotX(r * Math.cos(th)), plotY(r * Math.sin(th)))
      .stroke({ color: COL.center, width: Math.max(1.2, 2.4 * k), linecap: 'round' });
  }
  var chit = gTrans.circle(Math.max(8, 18 * k)).center(plotX(0), plotY(0)).fill('#000').opacity(0);
  inter(chit, 'Center (0, 0)', 'Center', 'The midpoint of both the transverse and the conjugate axis, and the ' +
    'crossing point of the two asymptotes.');

  /* foci */
  var showFoci = c < xm * 0.93;
  if (showFoci) {
    [c, -c].forEach(function (xv) {
      var d = gFoci.circle(Math.max(3.2, 8.4 * k)).center(plotX(xv), plotY(0)).fill(COL.teal).stroke('none');
      inter(d, function () { return 'Focus (' + xv.toFixed(2) + ', 0),  c = √(a²+b²) = ' + c.toFixed(2); },
        'Focus', 'The foci sit at (±c, 0) with c² = a² + b². They always lie beyond the vertices, outside the ' +
        'guide rectangle.');
    });
  }

  /* ── labels (leader-arrow annotations) ── */
  annot(gLabA, 'Conjugate axis', -0.40 * RX, 0.84 * RY, 0, Math.max(0.45, 0.32 * b),
    'Conjugate axis', 'The segment of length 2b along the y-axis, from (0, −b) to (0, b). It carries no point of the curve.');
  annot(gLabB, 'Transverse axis', 0.36 * RX, 0.84 * RY, 0.55 * a, 0.05,
    'Transverse axis', 'The segment of length 2a joining the two vertices. For a horizontal hyperbola it lies on the x-axis.');

  annot(gLabA, 'Co-vertex', -0.21 * RX, Math.min(0.66 * RY, b + 0.9), 0, b,
    'Co-vertex', 'Endpoint (0, b) of the conjugate axis and a midpoint of the rectangle\'s top edge.');
  annot(gLabA, 'Co-vertex', -0.21 * RX, Math.max(-0.70 * RY, -(b + 0.9)), 0, -b,
    'Co-vertex', 'Endpoint (0, −b) of the conjugate axis and a midpoint of the rectangle\'s bottom edge.');

  var vxL = -Math.min(0.80 * RX, a + 1.95), vxR = Math.min(0.78 * RX, a + 1.85);
  annot(gLabB, 'Vertex', vxL, -0.29 * RY, -a, -0.08, 'Vertex', 'Left turning point (−a, 0).');
  annot(gLabB, 'Vertex', vxR, 0.26 * RY, a, 0.08, 'Vertex', 'Right turning point (a, 0).');

  if (showFoci) {
    var fxL = -Math.min(0.88 * RX, c + 1.25), fxR = Math.min(0.88 * RX, c + 1.25);
    annot(gLabA, 'Focus', fxL, 0.27 * RY, -c, 0.16, 'Focus', 'Focus at (−c, 0), c = √(a² + b²) = ' + c.toFixed(2) + '.');
    annot(gLabA, 'Focus', fxR, -0.29 * RY, c, -0.16, 'Focus', 'Focus at (c, 0), c = √(a² + b²) = ' + c.toFixed(2) + '.');
  }

  annot(gLabB, 'Center', 0.16 * RX, -0.62 * RY, 0.1, -0.12,
    'Center', 'The hyperbola is centered at the origin: x²/a² − y²/b² = 1.');

  function asyPoint(sign) {
    var x = sign * 0.55 * RX, y = -m * Math.abs(x);
    if (Math.abs(y) > 0.78 * RY) { y = -0.78 * RY; x = sign * Math.abs(y) / m; }
    return [x, y];
  }
  var pL = asyPoint(-1), pR = asyPoint(1);
  annot(gLabA, 'Asymptote', -0.35 * RX, -0.85 * RY, pL[0], pL[1],
    'Asymptote', 'The line y = (b/a)x, an extended diagonal of the guide rectangle.');
  annot(gLabA, 'Asymptote', 0.36 * RX, -0.85 * RY, pR[0], pR[1],
    'Asymptote', 'The line y = −(b/a)x, the other extended diagonal of the guide rectangle.');
}

/* ── view modes ───────────────────────────────────────────────────── */
function setOp(g, v, anim) {
  try { g.timeline().finish(); } catch (e) { }
  if (anim) { g.animate(280).attr({ opacity: v }); }
  else { g.attr('opacity', v); }
  g.attr('pointer-events', v > 0.05 ? 'auto' : 'none');
}

function applyView(anim) {
  var guides = 1, curve = 1, co = 1, foci = 1, labA = 1;
  if (viewMode === 'Guides only') { curve = 0; }
  else if (viewMode === 'Curve only') { guides = 0; foci = 0; co = 0; labA = 0; }
  setOp(gGuides, guides, anim);
  setOp(gCurve, curve, anim);
  setOp(gCo, co, anim);
  setOp(gFoci, foci, anim);
  setOp(gLabA, labA, anim);
  setOp(gTrans, 1, false);
  setOp(gLabB, 1, false);
  setOp(gAxes, 1, false);
}

function updateReadout() {
  var c = Math.sqrt(aVal * aVal + bVal * bVal);
  document.getElementById('eqReadout').innerHTML =
    'x²/a² − y²/b² = 1  →  x²/' + (aVal * aVal).toFixed(2) + ' − y²/' + (bVal * bVal).toFixed(2) + ' = 1' +
    '<br>a = ' + aVal.toFixed(1) + ' , b = ' + bVal.toFixed(1) +
    ' , c = √(a²+b²) = ' + c.toFixed(2) +
    '<br>asymptote slope ± b/a = ' + (bVal / aVal).toFixed(2);
}

/* ── interaction handlers ─────────────────────────────────────────── */
function update_aValue(v) { aVal = +v; drawAll(); applyView(false); updateReadout(); }
function update_bValue(v) { bVal = +v; drawAll(); applyView(false); updateReadout(); }
function toggle_guidesView(v) { viewMode = v; applyView(true); }

/* ── demo steps ───────────────────────────────────────────────────── */
var STEPS = [
  {
    title: 'The labeled hyperbola',
    narration: 'Start with the full figure: center at the origin, vertices on the red transverse axis, co-vertices on the light blue conjugate axis, foci farther out, and orange dashed asymptotes through the corners of the teal rectangle.',
    state: { aValue: 2.5, bValue: 2.5, guidesView: 'Guides + curve' }
  },
  {
    title: 'Guides alone',
    narration: 'Hide the curve. All that remains is a rectangle of half-width a and half-height b plus its extended diagonals — enough information to predict the entire hyperbola.',
    state: { aValue: 2.5, bValue: 2.5, guidesView: 'Guides only' }
  },
  {
    title: 'Stretch a: move the vertices',
    narration: 'Increase a. The vertices and the red transverse axis slide outward, the rectangle widens, and the asymptotes become shallower, so the branches pull apart and open more gently.',
    state: { aValue: 4.5, bValue: 2.5, guidesView: 'Guides + curve' }
  },
  {
    title: 'Stretch b: steepen the opening',
    narration: 'Now grow b with a fixed. The vertices do not move at all, but the taller rectangle steepens the diagonals and the branches flare open more sharply.',
    state: { aValue: 2.5, bValue: 4.5, guidesView: 'Guides + curve' }
  },
  {
    title: 'Curve only',
    narration: 'Turn the guides off. The same branches remain, now clearly hugging the invisible diagonals — the construction has vanished but its fingerprint is the curve\'s shape.',
    state: { aValue: 2.5, bValue: 4.5, guidesView: 'Curve only' }
  }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = (i % STEPS.length + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
  var ai = document.getElementById('aValueInput');
  var bi = document.getElementById('bValueInput');
  var gi = document.getElementById('guidesViewInput');
  ai.value = s.state.aValue; document.getElementById('aValueVal').value = s.state.aValue;
  bi.value = s.state.bValue; document.getElementById('bValueVal').value = s.state.bValue;
  gi.value = s.state.guidesView;
  aVal = +s.state.aValue; bVal = +s.state.bValue; viewMode = s.state.guidesView;
  drawAll(); applyView(true); updateReadout();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + STEPS.length + ' · ' + s.title;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ── boot + resize ────────────────────────────────────────────────── */
document.addEventListener('fig-resize', function () {
  fitAspect();
  drawAll();
  applyView(false);
});

fitAspect();
applyStep(0);
applyView(false);
window.__markRendered();
